(() => {
 'use strict';
 const A=window.LessonArticle;
 const p=s=>`<p>${s}</p>`,f=s=>`<p class="element-formula">${s}</p>`,note=s=>`<p class="element-note">${s}</p>`;
 const card=(id,label=id)=>`<a href="bulk.html#${id}">${label}</a>`,lab=id=>`<figure data-boundary-lab="${id}"></figure>`,legacy=i=>`<div data-boundary-legacy="${i}"></div>`;
 const stat='https://documentation-be.hexagon.com/bundle/MSC_Nastran_2025.1_Linear_Static_Analysis_User_Guide/raw/resource/enus/MSC_Nastran_2025.1_Linear_Static_Analysis_User_Guide.pdf';
 const qrg='https://documentation-be.hexagon.com/bundle/MSC_Nastran_2025.1_Quick_Reference_Guide/raw/resource/enus/MSC_Nastran_2025.1_Quick_Reference_Guide.pdf';
 const source=(url,label)=>`<a href="${url}" target="_blank" rel="noopener">${label} ↗</a>`;
 const sections=[
 ['meaning','境界条件は「何を既知とするか」',
 p('境界条件を考えるときは、実物の支持が<strong>どの方向に動けるか、どの方向の力を受け止められるか</strong>を先に整理します。動かない成分を指定すると、その条件を実現する反力が計算されます。力を指定すると、通常はその方向の変位が計算されます。固定という名称だけでは、対象の点・辺・面も、止める方向も決まりません。')+
 A.table(['与える条件','既知の量','求める量・確認すること'],[['変位境界（基本境界）','変位u、回転θ。ゼロも指定値の一つ','反力R、反モーメントM'],['力の境界（自然境界）','表面力t、節点力F、分布荷重','変位と変形。荷重のない自由面ではt=0'],['弾性支持','支持剛性と支持側の位置','支持の変位と伝達力の両方'],['多点拘束','複数成分の間の式','関係を満たす変位と拘束力'],['接触','接触候補面・隙間・接触則','接触している範囲、開き、滑り']])+
 legacy(0)+f('変位指定：u = d\n力指定：t = σn = t̄\n弾性支持の例：R = −ks(u − us)')+
 p('nは面の外向き法線、usは支持側の位置です。<strong>自由面の「力0」と固定面の「変位0」は別の条件</strong>です。同じ成分に力と変位を指定した場合、その力を独立に満たすよう変位が変わるのではなく、指定変位を保つ反力が調整されます。内部の要素接続による力は、外部から荷重を与えていなくても存在します。')],
 ['dofs','節点・成分・座標系を一組で読む',
 p("レールに載せた台は、レール沿いに動けます。台の節点を丸ごと固定すると、残すはずのこの移動まで消えます。")+
 p('拘束の対象は「節点全体」ではなく<strong>節点番号＋成分番号</strong>です。GRIDの1〜3は並進、4〜6は各軸まわりの回転。どの軸かはGRIDのCDで決まります。CPは節点位置を記述する座標系であり、CPを変えただけではSPCの方向を指定したことになりません。')+
 A.table(['対象','自由度の扱い','拘束を選ぶ際の要点'],[['棒・梁','梁は並進・回転を使う。棒では曲げを伝えない','その要素が持たない剛性を、支持の意味と混同しない'],['シェル','並進と回転を使う。法線まわり回転の扱いは要素による','面内・曲げ・ドリリングの役割を分ける'],['通常の構造ソリッド','要素の変位場は節点並進で表す','面上の複数点の並進で物体の回転も止める'],['SPOINT','方向を持たない1個の未知数','並進・温度・相対量など、何を表す変数かを自分で定義する']])+
 p('ソリッドにつながるGRIDに456を指定しても、要素の回転を直接固定する境界にはなりません。例えば端面の全点の123を止めると、面が移動・回転するために必要な並進が止まり、固定端を表せます。逆に一点の123だけでは、その点まわりの剛体回転が残ります。')+
 p('回転の正方向は右手系、角度の単位はradです。円筒・球座標のCDでは、同じ成分番号でも節点位置により物理方向が変わります。詳細は'+card('GRID')+'、'+card('GRDSET')+'、<a href="coordinates.html#systems">座標の教材</a>へ。')],
 ['supports','固定・ピン・ローラーで変形が変わる',
 p('棚板を二つの台に載せて押します。板がたわむと端は傾きます。ローラーの上なら横にも滑れます。端を万力で挟むと傾けず、曲げを支えるモーメントが生まれます。下の図で中央に同じ荷重を掛け、たわみと端の傾きを見比べてください。')+
 lab('supports')+
 f('同じ中央荷重P、長さL、曲げ剛性EI\nピン・ローラー：w(L/2) = PL³/(48EI)\n両端固定：w(L/2) = PL³/(192EI)\nしたがって w固定 / w単純支持 = 1/4')+
 p('両端固定では端の傾きも0にするため、曲げモーメントを支持が受け持ちます。変位が小さいことだけで精度が上がったとは判断できません。支持の過剰な固定でも、もっともらしい小さな変位が得られます。')+
 A.table(['平面内x–yの梁の例','物理的に止める成分','別に確認する成分'],[['左ピン','ux、uy','θzは自由。面外成分は平面モデルの仮定に合わせる'],['右ローラー（水平面）','uy','uxとθzを許す。両端uxを止めると熱伸びも拘束する'],['固定端','ux、uy、θz','3次元では残る成分も固定するかを検討する']])],
 ['rigid-body','拘束を6個付ければ十分、ではない',
 p("支えを外した部品を横へ一様にずらします。形も材料の長さも変わりません。部品をいくら硬くしても、この動きを止める支持は生まれません。")+
 p('変形しない物体でも、3方向へ移動し、3軸まわりに回転できます。この6つが3次元の剛体運動です。普通の拘束付き静解析では、その運動を支持が止める必要があります。重要なのは拘束の数ではなく、<strong>独立な運動を止める位置と方向</strong>です。')+
 f('点r=(x,y,z)の剛体変位：u(r) = t + θ × r\nux = tx + θy z − θz y\nuy = ty + θz x − θx z\nuz = tz + θx y − θy x')+
 p('各支持成分へこの式を代入すると、剛体運動q=[tx,ty,tz,θx,θy,θz]に対するCq=0ができます。Cの独立な行の数を階数rank(C)と呼び、剛体運動だけに限れば残る自由度は6−rank(C)です。')+
 lab('rigid')+
 p('非一直線上のAで123、ABがx方向のBで23、xy面のCで3を止める3–2–1配置は、一例として6運動を除けます。ただし<strong>自由膨張や実物の荷重経路まで正しく表すことは別問題</strong>です。熱膨張試験などの最小支持では、支持反力が本来ほぼ0かを調べます。部品が複数に分離していれば、それぞれの剛体運動と接続を点検します。')],
 ['coordinates','斜めの支持を正しい成分で指定する',
 p('摩擦のない案内面では、止めるのは法線方向の変位で、接線方向の変位は許します。法線nが全体軸と一致しなければ、全体xやyをそのまま止めると別の支持になります。CDの局所軸を法線へ合わせる方法と、複数の成分を式で結ぶ方法があります。')+
 f('n = [cosφ, sinφ]ᵀ、接線 t = [−sinφ, cosφ]ᵀ\n止める条件：nᵀu = cosφ ux + sinφ uy = 0\nu = t q と置けば、許す運動は接線変位qだけ')+
 lab('inclined')+
 p('操作例はK=kIなので、つり合いKu=F+RとR=−n(nᵀF)から、u=(I−nnᵀ)F/kです。法線反力は許された変位と直交し、Rᵀu=0となります。異方的な剛性や周囲の部材がある一般モデルでは、この単純な投影式ではなく全体を解きます。')+
 p('入力前に支持面の法線、CDの各軸、SPCの成分を同じ図で確認します。変位・SPCFORCESを異なる座標系のまま成分ごとに足し合わせないことも重要です。'+card('CORD2R')+' / '+card('CORD2C')+' / '+card('MPC')+'。')],
 ['symmetry','対称・反対称・自由面を見分ける',
 p('対称モデルは、形状だけでなく材料方向、荷重、接続、支持が同じ対称性を持つときに使えます。形だけ半分にして端面を自由にすると、切った先の構造が伝えていた作用を失います。対称面は自由面でも固定面でもありません。')+
 '<div data-boundary-static="symmetry">'+window.BoundaryLabs.symmetryFigure()+'</div>'+
 A.table(['鏡面の法線（CDの軸と一致）','対称：0にするGRID成分','反対称：0にするGRID成分'],[['x','1、5、6','2、3、4'],['y','2、4、6','1、3、5'],['z','3、4、5','1、2、6']])+
 p('対称条件では法線並進と面内軸まわりの回転を0にします。反対称条件では面内並進と法線軸まわりの回転を0にします。表の回転成分は、その回転自由度を使う要素に対する条件です。ソリッドでは該当する並進成分を使い、456を追加して代用しません。')+
 f('xを反転する行列 S = diag(−1,1,1)\n対称変位：u(−x,y,z) = S u(x,y,z)\nx=0では ux = −ux → ux=0\n回転は軸性ベクトル：θ(−x,y,z) = −S θ(x,y,z)\nしたがって θy=θz=0')+
 p('一般荷重を対称成分と反対称成分へ分けて結果を重ねる方法は、線形の同一モデルで成立します。接触の開閉、塑性、大変形がある場合は同じ重ね合わせを適用できません。固有値・座屈では対称条件を置くと反対称モードが除外されるため、対称ケースだけで最低固有値を判断しないようにします。')+
 p('左右対称な平板100 mm²に一様な面圧2 N/mm²を掛けると、全体には200 Nが働きます。半分の板では同じ面圧を50 mm²に掛けるので100 Nです。残した半分の各点は元の板と同じように動きます。半分になるのは受け持つ荷重で、同じ場所のたわみを2倍に戻す必要はありません。')+
 p('対称面上に残る集中質量や梁・補強材も、半モデルが担当する質量・剛性を重複して計上しないようにします。断面を実際に切り分ける場合と、中心線上の等価な梁へ縮約する場合を分け、断面積・各曲げ剛性・ねじり剛性・偏心を確認します。全体の合力・質量は分割割合を戻して比較し、対称性に従って復元した同じ位置の変位・応力を単純に2倍にはしません。対称な条件でも非対称な分岐が起こる非線形問題では、対称モデル自体がその経路を除いてしまう点に注意します。')],
 ['sets','一つの点で、止める向きと残す向きを決める',
 p('レール上の台車を横から押すとレールが押し返します。レールに沿って押すと台車は進めます。同じ車輪でも、どの向きに働く力かで支えの役割は違います。')+
 legacy(1)+
 p('支持を考えるときは「この点は固定」と一語で済ませず、実物で許す動きを一つ挙げます。左右の支承で橋を鉛直に支え、片側は長手方向に滑れるようにすると、温度が上がった橋が伸びる余地が残ります。両側とも長手方向を止めると、橋は支承を押します。')+
 p('Inputで支持を記述する → '+card('SPC')+' · '+card('SPC1')+' · '+card('SPCADD')+'。ケースごとの有効な支持は<a href="analysis.html#constraint-check">解析の「拘束の入力と反力」</a>へ。')],
 ['imposed','強制変位では反力が答えになる',
 p('棒の左端を止めて右端を右へ2 mm動かすと、棒は2 mm伸びます。両端をともに右へ2 mm動かせば、途中に別の支持や荷重がない一様な棒は形を保ったまま移動します。伸びを決めるのは左右の変位の差です。')+
 lab('imposed')+
 p('図では右端の位置を指定し、左端との間にある二つのばねを引きます。どちらにも同じ引張力が伝わるので、柔らかいばねほど長く伸びます。')+
 legacy(2)+
 p('動く支持の入力は'+card('SPCD')+'へ。')+
 p('既知の移動量を与える解析でも、支持装置の柔らかさを含むかによって反力は変わります。試験機のクロスヘッド変位と試験片の標点間変位を混同せず、何の相対変位を指定するのかを決めます。')],
 ['partition','指定変位を右辺へ移す計算を追う',
 p("橋の支承が1 mm沈んだとします。解析前から分かるのは支承の移動で、途中の節点の変位と、支承が橋を押し返す力は未知です。")+
 p('自由な成分をf、既知の変位成分をsとし、us=dと置きます。拘束成分にも外荷重Fsが加わり得るので、反力Rsと分けて書きます。全体のつり合いKu=F+Rを行ごとに分けると、次の2式です。')+
 f('Kff uf + Kfs d = Ff\nKsf uf + Kss d = Fs + Rs\n\n① 自由成分を解く：Kff uf = Ff − Kfs d\n② 既知値dと組み直す\n③ 反力を回復：Rs = Ksf uf + Kss d − Fs')+
 p('指定変位は、自由成分にとって−Kfs dという等価な右辺項になります。拘束行を消すだけでこの項を移さないと、ゼロでない支持変位が周囲へ伝わりません。反力を計算するときには、消す前の剛性行が必要です。')+
 f('前節の2ばね：k1=100、k2=300 N/mm\n中間点Cのつり合い：k1(uC−0) + k2(uC−d) = P\n(k1+k2)uC = P + k2 d\nuC = (P + k2 d)/(k1+k2)\nRA = −k1 uC、RB = k2(d−uC)')+
 f('d=0.2 mm、P=0の場合\nuC = 300×0.2/400 = 0.15 mm\nRA=−15 N、RB=+15 N\nU=½×100×0.15² + ½×300×0.05² = 1.5 N·mm\n½ RB d = ½×15×0.2 = 1.5 N·mm')+
 p('最後の仕事は、指定変位を0から比例的に増やした線形弾性問題の検算です。拘束点の外荷重、非ゼロ右辺のMPC、温度や塑性がある場合まで、この式をそのまま適用しません。')],
 ['mpc','MPCの独立・従属を明確にする',
 p("小さく動かすてこで、支点の同じ側にある2点の移動距離を1対2に保ちます。一方を決めると他方の変位も決まる関係を式にできます。")+
 p('二つの動きに関係を一つ決めると、一方からもう一方が決まります。その式で求める側を<strong>従属成分</strong>、求めるために使う側を<strong>独立成分</strong>と呼びます。独立側の値は、支持で決まることも、構造のつり合いで初めて分かることもあります。')+
 f('例：Aの成分1を従属、Bの成分1を独立\n1×uA − 2×uB = 0\nuA = 2uB\nuB=0.3 mmと求まれば、uA=0.6 mm')+
 legacy(3)+
 p('「マスター節点」「スレーブ節点」という名称だけで判断せず、<strong>どの節点の何番成分が、どの式の先頭にあるか</strong>を記録します。同じ節点でも成分1が従属、成分2が独立という指定はあり得ます。拘束の式がつないだ成分以外には、その関係を適用しません。')+
 f('相対変位を出力する例：q − uB + uA = 0\n従属：SPOINTのq、独立：uA・uB\nq = uB − uA')+
 p('Aが右へ1 mm、Bが右へ3 mmなら、両点の開きはq=2 mmです。両方が右へさらに1 mmずつ動いても、開きは2 mmのまま。ここでqは二点間の物差しの読みです。両点を一緒に動かす継手を作るなら、最初からuB−uA=0という別の関係を使います。'+card('MPC','InputでMPCの先頭成分と係数を見る')+'。')],
 ['work','変位の関係から、力の伝わり方を導く',
 p("一端が1 mm、もう一端が2 mm動く理想てこでは、同じ仕事を渡すための力の大きさは逆比です。結び方は力の伝わり方にも効きます。")+
 p('拘束は変位を結ぶだけでなく、力の伝わり方も変えます。理想拘束が、許される微小な変位変化に対して仕事をしないことから導けます。ここでQは、拘束が各自由度へ及ぼす力です。')+
 f('uA = r uB + y（rとyは一定）\nδuA = r δuB\nδW = QA δuA + QB δuB\n    = (r QA + QB)δuB = 0\n任意のδuBに対して成立 → QB = −r QA')+
 lab('mpc')+
 p('操作例は、支持付きの理想的な比率機構を1方向の式で表しています。r≠1ではQA+QBが0とは限らず、機構の支点が残りの力を受けます。離れた2点を単に同じ方向へ直結したモデルと同一視しません。回転と並進を結ぶ場合、回転に対応する力はモーメントであり、腕の長さが係数に入ります。')+
 f('Bのつり合いへ代入すると\nkB uB = P + QB = P − r kA uA\n(kB+r²kA)uB = P − r kA y\n変位比rは、縮約剛性にはr²として現れる')+
 p('例えばq=(u1+u2+u3+u4)/4という1方向の平均変位に力Pを与えると、仮想仕事Pδqから各成分へP/4が伝わります。これは特定の式から導いた結果です。一般のRBE3の荷重分配を、いつでも節点数で割るだけと考えないでください。詳しい補間比較は<a href="elements.html#rigid">剛体・補間要素</a>へ。')],
 ['nonhomogeneous','二つの点に決まった変位差を与える',
 p('同じ方向を正とした二点で、Aを常にBより0.2 mm余分に動かすとします。Bが0.3 mm動いたとき、Aは0.5 mmです。差を保ったまま、両点が一緒に動く自由は残ります。')+
 p('uA−uB=0なら動く量は同じ、uA−uB=0.2 mmなら差が残ります。この右辺を持つ式の入力は'+card('MPCY')+'・'+card('MPCD')+'へ。')+
 '<details><summary>式で確かめる：指定した変位差がつり合いにどう入るか</summary>'+
 f('拘束式を独立n・従属mに分ける：Cn un + Cm um = y\num = −Cm⁻¹Cn un + Cm⁻¹y = G un + c\nu = Tq + g、T=[I;G]、q=un、g=[0;c]')+
 p('ここでCmが逆行列を持たなければ、選んだ従属成分を求められません。Ku=F+Qへu=Tq+gを代入し、左からTᵀを掛けます。許される変位変化δu=Tδqに対してQの仮想仕事は0なので、TᵀQ=0です。')+
 f('K(Tq+g) = F+Q\nTᵀKTq + TᵀKg = TᵀF\nしたがって K̃q = F̃\nK̃ = TᵀKT\nF̃ = Tᵀ(F−Kg)')+
 f('ブロックで書くと\nK̃ = Knn + KnmG + GᵀKmn + GᵀKmmG\nF̃ = Fn + GᵀFm − (Knm + GᵀKmm)c')+
 p('非ゼロの指定値から−Kgという項が生じます。同じ係数で指定値だけを変えると、縮約剛性を保ったまま右辺が変わります。')+'</details>'],
 ['redundancy','三つの点を結ぶと、どの動きが残るか',
 p('AとBを同じだけ動かし、BとCも同じだけ動かします。これで三点は一緒に動けます。図の条件を一つずつ変えてみてください。')+
 lab('conflict')+
 p('さらにAとCを同じだけ動かしても、許された動きは変わりません。ところが「AはCより1 mm多く動く」を加えると、三点の置き場所が見つかりません。一方「Aを地面に留める」を加えると、三点とも止まります。同じ条件の繰り返し、両立しない条件、本当に動きを一つ減らす条件を区別できます。')+
 p('同じ成分をMPCとSPC1で指定した場合の直し方は、<a href="analysis.html#constraint-check">解析の「拘束の入力と反力」</a>へ。')],
 ['rbe','SPC・MPC・RBE2・RBE3の選択',
 p("ボルト穴に荷重を配るとき、穴の周りは変形してよいのか、厚いワッシャーと一体で動くのかを先に考えます。")+
 A.table(['方法','適する場面・長所','短所・避けたい使い方'],[['SPC／SPC1','地面に対する既知の支持を端的に指定','部品同士の追従や支持の柔らかさは表さない'],['MPC','相対変位・平均・比率など明示した線形関係','係数・座標・単位・従属成分の管理が必要'],['RBE2','剛な治具、剛体運動を保つ結合','選んだ領域の変形を抑え、熱変形や局所応力を変え得る'],['RBE3','周囲の動きから参照点を補間し、荷重を分配','支持そのものではない。配置・成分・重みで表せる運動が変わる'],['CBUSHなど弾性結合','実測・設計値に基づく有限の結合剛性','剛性を決める根拠と座標が必要。十分大きい値の安易な代用は不適切']])+
 p('RBE2の独立点を作っただけでは、その点が地面へ固定されたことにはなりません。RBE3の参照点に荷重を与えられることと、その参照点が独立側かどうかも別です。標準的なUMなしのRBE3では参照成分が従属であり、そこへSPCを重ねると競合し得ます。')+
 p('詳しい比較と操作図は<a href="comparisons.html#rigid-interpolation">似たカードの使い分け</a>、式・重み・剛体回転は<a href="elements.html#rigid">剛体・補間要素</a>に集約しています。この章では、支持と部材間結合を選ぶ判断に使います。'+card('RBE2')+' · '+card('RBE3')+' · '+card('CBUSH')+'。')],
 ['interfaces','点・辺・面の接続と、モーメントの受け渡し',
 p('梁の端には並進と回転がありますが、通常のソリッド節点には要素の回転自由度がありません。梁の回転をソリッドの一点の「回転番号」に結んでも、周囲のソリッドへ曲げモーメントを伝える仕組みにはなりません。面上の離れた点の力の組として受け渡す必要があります。')+
 '<div data-boundary-static="interface">'+window.BoundaryLabs.interfaceFigure()+'</div>'+
 f('2点が距離hだけ離れ、逆向きの力±Fを受ける\n合力 = F−F = 0\nモーメントの大きさ M = Fh\nMを渡すには F = M/h')+
 p('結合範囲を小さくすると同じMを伝える力が大きくなり、局所応力も変わります。剛体結合で面を固めるか、補間で分配するか、実際の接合部をモデル化するかを、評価したい量に合わせて選びます。全体変位の比較で使える理想化が、そのまま接合部近傍の強度評価に適するとは限りません。')+
 p('非一致メッシュの結合では、位置が近いことだけでなく、許す滑り・回転・面外変形が連続するかを確かめます。詳しい図とパッチ補間は<a href="elements.html#connector">結合要素</a>、ソリッドの変位場は<a href="elements.html#solid">ソリッド要素</a>へ。')],
 ['releases','梁の端部解放と、支持条件の役割',
 p("2本の梁をピンでつなぎます。継ぎ目の位置をそろえたまま、梁の傾きは左右で違ってよい結合です。")+
 p('梁端のPA／PBは、その要素端で伝える成分を解放する指定です。接続する節点全体の支持条件を指定するSPCとは役割が違います。例えば同一節点へ集まる2本の梁では、節点の並進を共有しながら、部材間でどのモーメントを伝えるかを解放で決めます。')+
 p('番号1〜3は並進に対応する軸力・せん断力、4〜6はねじり・曲げモーメントです。SPCの番号と見た目が同じでも、PA／PBは要素座標系で読みます。CDの軸や全体軸だと誤解すると、違う成分を解放します。')+
 p('接続の回転が自由であることと、両要素のPA／PBへ同じ数字を必ず記入することは同義ではありません。どちらの端で力・モーメントが伝わるか、共有された節点回転が他要素・支持でどう使われるかを追います。両側を解放して未使用の節点回転だけを残すと、特異性の原因になります。具体例と既存の図は<a href="elements.html#beam-pin">梁要素の端部解放</a>で確認し、ここでは重複掲載しません。')],
 ['compliance','支持の柔らかさと、大きな剛性による代用',
 p('ゴムを挟んだ継手に100 Nを伝えます。ばね剛性が1,000 N/mmなら、両端は力の向きに0.1 mmずれます。一方、二点の変位を等しく結ぶと、そのずれは常に0です。柔らかさを持つ結合を選ぶ理由は、実物にこの相対変位があるかどうかです。')+
 f('直列の部材kbと支持ksに同じ力Pが伝わる\nu = P/kb + P/ks\n固定支持の場合 u0=P/kb\n相対差 (u−u0)/u0 = kb/ks')+
 lab('compliance')+
 p('支点を柔らかくした比較では、全変位に加えて支持反力の分担、局所応力、固有振動数も調べます。複数の支持がある不静定構造では、支持の柔らかさが荷重分担を変えます。入力したばね定数が「部品一つの剛性」か「面積当たりの係数」かを区別し、節点数を増やして総剛性まで増やさないようにします。')+
 p('ペナルティ法の一般形は、拘束違反Cu−dに大きな係数を掛けて抑えるものです。エネルギー½α‖Cu−d‖²を加えると、剛性はK+αCᵀC、右辺はF+αCᵀdになります。αを上げると違反は減り得ますが、無条件に精度が良くなるわけではありません。これは方法の説明であり、NastranのSPCが常にこの方法で処理されるという意味ではありません。')],
 ['autospc','弱い向きと、実物が支える向き',
 p('二本のばねで支えた点を押します。横向きには硬いばねが効いても、縦向きにはほとんど抵抗しないことがあります。下の図でばねの向きを回して、動きやすい方向がどう変わるか見てください。')+
 f('局所剛性の主値 λi と最大主値 λmax\n比 Ri = λi / λmax（λmax>0）\n弱い主方向と、GRIDの成分軸は一致するとは限らない')+
 lab('autospc')+
 legacy(4)+
 p('使っていない自由度を計算から外すことと、実物の支えを追加することには違いがあります。例えば接合部が外れて動いているなら、そこで動きを止めても、本来の接合部を通って力が伝わるようにはなりません。<a href="analysis.html#constraint-check">自動拘束の出力を読み、原因を切り分ける →</a>')],
 ['freebody','拘束不足・内部機構・自由支持モデル',
 p('構造全体がそのまま動く剛体運動、部材が相対的に動く内部機構、要素が使わない自由度を区別します。剛体運動を止めても、ピンでつながる四角形がせん断変形する機構などは残ります。局所ブロックを調べるAUTOSPCだけで、すべての全体機構を見つけられるとは限りません。')+
 A.table(['状況','意味','確認・次の行動'],[['通常の静解析で全体が自由','変位の一意性や荷重のつり合いに問題','実物の支持を確認。便宜的な固定で済ませない'],['自由支持の実固有値解析','剛体モードが理論上含まれる','単一の連続3次元物体では通常6モード。部品数と機構も確認'],['未使用の節点回転','要素がその回転に剛性を持たない','実際の変形モードと区別して処理する'],['慣性リリーフ','自由物体の荷重を慣性力とつり合わせる','質量・荷重・剛体加速度・支持基準を専用手順で確認']])+
 p('自由物体で外力がつり合っていても、剛体変位の基準は定まりません。変形・応力が存在し得ることと、Ku=Fからすべての変位が一意に決まることは別です。小さなばねで便宜的に支える場合も、そのばねの反力・エネルギー・結果への感度を確認します。')+
 p('SUPORT／SUPORT1は剛体運動の基準となる自由度を指定するもので、通常のSPCの代用品ではありません。慣性リリーフではINRELの方式などと合わせて使います。適用条件は'+card('SUPORT')+' / '+card('SUPORT1')+'へ。')],
 ['reactions','反力は合力とモーメントの両方で確かめる',
 p("棚の先端に下向き100 Nを載せます。壁から返る力が上向き100 Nでも、荷重点が壁から離れていれば棚を回そうとする作用が残ります。")+
 lab('reactions')+
 f('静的な全体つり合い\nΣF外 + ΣR支持 = 0\nΣM外,O + Σ[(r−rO) × R支持] + ΣM支持 = 0')+
 p('棚板と支柱を一緒に囲むと、板と柱の間の押し合いは内部で打ち消し合います。板だけを取り出せば、柱が板を押す力は外から受ける力です。まず何を取り出したかを決めると、同じ接合部の力を二度足さずに済みます。')],
 ['diagnosis','台に載せただけの板は、下へ引き止められるか',
 p('板を左の台Aと、そこから300 mm右の台Bに載せます。板の自重を無視し、Aから400 mmの張り出し先端に下向き100 Nを掛けます。板が両方の台に載ったままだと仮定してみます。')+
 window.BoundaryLabs.overhangFigure()+
 f('Aまわりのつり合い：RB × 300 = 100 × 400 → RB ≈ 133 N（上向き）\n鉛直方向のつり合い：RA = 100 − RB ≈ −33 N（下向き）')+
 p('この答えは、Aで板を約33 N下へ引き止める必要があるという意味です。ボルトで留めていれば可能ですが、ただ載せただけの台は板を下へ引けません。その場合、A側は浮き、元の姿勢で二点に載ったままという仮定が崩れます。')],
 ['scope','同じ壁でも、止める物理量が違う',
 p('振動台に固定した部品は、台に対しては動かなくても、外から見れば台と一緒に揺れます。また断熱壁を通る熱はゼロでも、壁の温度は変わり得ます。「固定」や「ゼロ」と書く前に、何に対する動きか、何の量を止めるかを言葉にします。')+
 p('支持の指定とつり合いの出力は<a href="analysis.html#constraint-check">解析の「拘束の入力と反力」</a>へ。') ]
 ];
 sections.push(
 ['coincident','同じ位置の節点を共有するか、二つに分けるか',
 p('実物の継ぎ目で、左右にどんな相対運動を許すかを決めます。GRIDの位置は初期形状を、各要素が参照するGRID番号は変位を共有する範囲を決めます。同じ位置にある別番号の2点は、通常の要素接続では独立です。')+
 A.table(['継ぎ目で許す運動','選び方','結果で見ること'],[
 ['連続材で両側が一緒に動く','適合メッシュで同じGRIDを共有。梁では端部解放の有無も確認','要素が使う変位成分が連続。通常のソリッドには節点回転剛性がない'],
 ['並進は一致、一軸まわりの回転は自由','同位置の別GRIDで必要成分だけをMPC等で結ぶ、または梁端の対象成分を解放','両側の並進差、許した相対回転、解放軸の端モーメント'],
 ['ずれに比例して力を伝える','別GRIDの間に方向と剛性を指定したばね','軸をそろえた両点の相対変位とばね力'],
 ['離れると力を伝えず、当たると押す','既知の点対にはCGAP／PGAP。接触位置が移るなら面接触を検討','初期すきま、接触の開閉、圧縮力、開いた後の荷重経路']])+
 p('接合部に重複節点があるからといって一括統合すると、意図したヒンジ・ばね・接触を消してしまいます。反対に連続材の節点が未結合だと、自由辺や部品の相対運動が現れます。<a href="elements.html#rigid-hinge">RBARヒンジの手計算</a> · <a href="elements.html#gap">GAP要素の使い方</a>。')],
 ['soil-extent','建物・基礎・地層を一枚の断面に描く',
 p('例は、軟らかい地層の上に建つ建物の地震応答です。知りたい量を「基礎Aの水平加速度と、建物が傾く量」と決めます。まず基礎を描き、その周囲で変形する土、揺れを増幅させる地層、その下の硬い層を描きます。ここまでは実際の断面です。次に、計算する範囲だけを線で囲みます。')+
 '<figure data-soil-lab="soilExtent"></figure>'+
 p('<strong>地表と地層の境目は実在します。</strong> 建物が載っていない地表には、空気からの力を無視するなら表面力ゼロを与えます。ここで波が反射するのは物理現象です。土と岩の境目では、密度や波速の違いに応じて波が反射・透過します。一方、図の左右と底の太線は計算を打ち切った位置です。実物の壁として扱うと、現地にない反射が加わります。')+
 p('側面は、基礎の近くで土が強く変形する範囲や、検討に含める斜面・地層の段差の外に置きます。底面は、地層調査と入力地震動がどの深さを表すかから決めます。図では岩の上端で切る場合と、岩の一部も要素にする場合を比較できます。底を深くしたら、その深さに対応する物性と入力波も見直します。図の20 m・40 mは感度を調べる例です。')],
 ['soil-side','側面には、建物の外まで続く地盤を表す',
 '<figure data-soil-lab="soilSide"></figure>'+
 p('<strong>建物をいったん外したら、同じ深さの土はどう揺れるか。</strong> これが自由地盤の揺れです。水平に広がる成層地盤に下から鉛直に平面波が入る例なら、同じ地層を持つ縦一列のモデルで深さごとの動きを計算できます。図のFFがその列です。地表の「自由面」は表面力に関する条件で、自由地盤は地中も含む基準の応答です。')+
 A.table(['側面の扱い','この断面で起きること'],[
 ['側面を固定する','側面の変位がゼロになり、そこに届いた波が反射して基礎側へ戻ります。自然に揺れる遠方地盤を表したいときの誤設定を確かめる比較用です。'],
 ['自由地盤境界','同じ深さで本体地盤とFFを結びます。代表的な方式ではFFから伝わる力を与えたうえで、両者の速度差にダンパーが働きます。速度がともに10 cm/sならダンパー力はゼロ。本体が12、FFが10 cm/sなら差の2 cm/sに抵抗します。'],
 ['エネルギー伝達境界','切断面の外へ同じ水平地層が続くと仮定し、外部地盤の波動解から、境界の動きに対して外側が返す力を求めます。建物から外へ進む波が運ぶエネルギーを表せます。外側に急な地層変化がある場合は、その変化を要素で含めるか、外部の仮定を見直します。']])+
 p('底から地震を入れる場合、側面でも元の地盤は揺れます。側面の全節点を静止点へのダンパーでつなぐと、建物がなくても地盤に抵抗力が生じ得ます。自由地盤とつなぐ理由は、入ってくる地震の揺れを保ちながら、建物の影響で外へ向かう波を受け渡すことにあります。')],
 ['soil-base','底面では、入れたい波と出ていく波を分ける',
 '<figure data-soil-lab="soilBase"></figure>'+
 p('図は水平に揺れるせん断波（S波）が下から来る場合です。上向きの矢印は<strong>波が進む方向</strong>、左右の両矢印は<strong>土の粒子が動く方向</strong>です。建物や地表・地層境界で生じた波の一部は下向きに戻ります。そこで、基盤より下をどう扱うかを決めます。')+
 A.table(['底面の選択','与えるもの','下へ戻る波の扱い'],[
 ['剛基盤を仮定','底面の運動を指定する。地盤内のその深さで想定する全波（上昇波＋下降波）と、指定する運動を整合させる','底面は指定した運動に従う。そこから下への波の逸散を直接表さず、戻り波を反射させる。硬い層を剛体と扱えるかを判断する'],
 ['下方へ続く弾性基盤を仮定','例えば粘性底面と入射波に相当するせん断力を組み合わせる。密度・波速・負担面積と、ソルバーの入力波の定義をそろえる','上昇波を入れながら、下へ戻ってきた波を基盤の外へ逃がす。底面の運動は計算で決まる']])+
 p('地表で観測した加速度には、表層を通ったときの増幅や反射が含まれます。その記録をそのまま底面に与え、表層をもう一度通すと、揺れを過大にも過小にも評価し得ます。記録が<strong>地表・露頭・地中のどこで得られたか</strong>、解析の入力欄が<strong>入射波・全波のどちらを要求するか</strong>を先に確かめます。地表記録の一律半分を底面へ入力する手順は使えません。')],
 ['soil-check','模型の幅を広げると、戻ってくる波はどう変わるか',
 p('基礎から出た波を、同じ場所Aで待ち受けます。実際の地層の境目は同じ位置に留まりますが、計算の都合で置いた側面は外へ移せます。動かした側面で折り返す波だけは、往復する道のりが長くなります。')+
 p('例としてAから真横へ出たS波が同じ経路で戻るなら、往復時刻の目安は 2L/Vs です。Vs=200 m/sで、L=20 mなら0.20秒、40 mなら0.40秒。これは散乱波がAを出てからの経過時間で、層内反射やP波には別の経路・波速が効きます。人工境界を遠ざけると遅れる成分は、波形を切り分ける手掛かりになります。')+
 p('ダンパーの係数や反射波の符号を確かめるには<a href="theory.html#boundary/viscous">波の反射と粘性境界</a>へ。扱いたい振動数に対する要素寸法は<a href="theory.html#mesh/waves">波長・せん断波速度・時間刻み</a>で確認できます。')],
 ['reflection','地盤を途中で切ったとき、何が戻ってくるか',
 p('半無限の地盤を有限の範囲で切ると、本来は遠方へ進む波がモデルの端まで到達します。人工的な端を固定すると変位・粒子速度の反射波は逆符号、自由端では同符号になります。これは同一媒質中を垂直に入射する一次元波の説明です。応力波の符号を読むときは逆の関係です。')+
 '<figure data-mesh-wave-lab="reflect"></figure>'+
 p('同じ材料の中で境界の位置だけを外へ動かすと、境界からの反射波は観測点に遅れて届きます。層境界など物理的に存在する反射は、その位置で生じます。実在する自由表面まで吸収端へ変更すると、必要な反射を消してしまいます。')],
 ['impedance','法線・接線の速度を、境界に作用する力へ変える',
 p("波がモデルの右端に届くとき、外側へ続く土も動かされます。その土がどれだけ押し返すかを境界の動く速さから表します。")+
 p('局所粘性境界は、境界の外側へ進む波が運ぶ力と速度の関係をダッシュポットで近似します。均質・等方な線形弾性体に垂直入射する平面波を考え、密度をρ、縦波速度をVp、せん断波速度をVsとします。nは境界の法線、tは面内の接線です。')+
 f('応力と粒子速度の比（波動インピーダンス） Zp = ρVp、Zs = ρVs<br>静止した外部に対する境界表面力　tn = −Zp vn、tt = −Zs vt<br>節点の負担面積をAiとして　cn,i = ρVp Ai、ct,i = ρVs Ai<br>節点力 Fi = −ci vi　　仕事率 Fi vi = −ci vi² ≤ 0')+
 p('Vs=200 m/sは、波の山が隣の場所へ伝わる速さです。一つの土粒子が200 m/sで横へ飛ぶわけではありません。ダンパーに入る速度vtは、その場で粒子が揺れる速さです。ρ=1,800 kg/m³、Ai=2 m²なら接線方向の係数はρVsAi=720,000 N·s/m。粒子が右へ0.01 m/sで動く瞬間、左向きに7,200 Nが働きます。境界を細分化しても、各節点の負担面積の合計は同じです。')+
 p('速度がゼロのとき、この抵抗力もゼロです。静的な支持や初期地圧の釣合いは別途必要です。地震波を外から入力する自由地盤境界では、基準地盤との相対速度と外部地盤からの作用を扱います。各節点を一律に静止地面へ結ぶだけで同じ条件にはなりません。')],
 ['return-wave','反射係数・往復時間で設定を検算する',
 p("揺れが観測点を過ぎて右へ進み、しばらくして同じ点に別の山が届きました。境界までの往復時間と遅れを比べると、戻り波かどうかを調べられます。")+
 f('垂直入射の一次元速度波。対象面積Aの媒質の係数 C = ρcA、境界の係数をDとすると<br>速度振幅比 Rv = (C−D)/(C+D)。反射エネルギー比 = Rv²<br>D=Cなら0、D=C/2ならRv=1/3、戻るエネルギーは1/9')+
 p('境界から距離Lだけ内側に観測点を置き、短いパルスを与えます。均一媒質なら入射波から約2L/c後に戻る成分を探します。観測する速度成分・符号・時間刻みは比較間でそろえます。斜入射、表面波、異方性や複雑な地層では、係数を合わせても反射が残り得ます。領域を拡げた場合と観測波形・ピークを比べます。')+
 p('この係数は局所吸収境界の一般理論です。Nastranで等価なダンパを配置する際は、対象SOL、基準側の運動、各方向、単位、対象面積を確認します。材料減衰を増やして反射を隠すと、観測したい入射波まで変わります。<a href="theory.html#mesh/waves">波長・時間刻み</a> · <a href="theory.html#damping">減衰の理論</a>。')]
 );
 const questions=[
 ['ソリッドの一点を123456で止めれば、その点を中心とする回転も止まる？','通常の構造ソリッドの変位場は並進で表されます。一点の並進を止めても、その点まわりの剛体回転は残ります。離れた点・面の並進によって必要な回転を止めます。'],
 ['Aを123、Bを23、Cを3で止めた。3点がx軸上なら十分？','6条件のうち独立なのは5です。x軸まわりの剛体回転では3点の並進が変わらないので、その回転を止められません。'],
 ['法線n=(cos30°,sin30°)。ux=0.25 mm、uy=−0.433013 mmならガイド条件を満たす？','n·u=0.866025×0.25+0.5×(−0.433013)≈0です。xとyの両方が0でなくても、法線変位は0です。'],
 ['xを法線とする対称面で、梁・シェルの何を止める？','x方向並進とy・z軸まわりの回転です。CDが同じ軸なら156。反対称なら234。ソリッドでは対応する並進条件を使います。'],
 ['同じ中央荷重の梁で、単純支持の中央変位が0.064 mm。両端固定なら？','同じEuler–Bernoulli梁なら1/4の0.016 mm。小さい変位が正解とは限らず、実物が回転を止めるかで選びます。'],
 ['k1=100、k2=300 N/mmの直列ばね。A=0、B=0.2 mm、中間の外力0なら中間変位と反力は？','uC=300×0.2/(100+300)=0.15 mm。右向きを正にしてRA=−15 N、RB=+15 N。両方のばねの伸びを足すと0.2 mmになります。'],
 ['MPCのuA−2uB=0で、Aが従属。Bは既知値として入力しなければいけない？','いいえ。Bも通常は全体の剛性方程式から求める未知数です。Bが求まればA=2Bで回復します。'],
 ['二点間の開きを測っています。AもBも右へ1 mmずつ動いたら、読みはどう変わる？','変わりません。q=uB−uAなので、共通の移動は差し引かれます。開きを測るだけなら二点の動きは自由です。'],
 ['uA=2uBの拘束で、Aへの拘束力QA=30 NならBへの拘束力QBは？','2QA+QB=0なのでQB=−60 N。許される変位変化に対して仕事が0になる関係です。この比率機構の支点が残りの力を受けるため、単純な二点直結の作用反作用とは分けます。'],
 ['uA−uB=0.2 mmで、Bが−0.1 mm動いたらAはどこにいる？','uA=uB+0.2なので、Aは+0.1 mmです。二点の変位が逆向きでも、指定した差は保たれています。'],
 ['支持と部材を直列ばねで近似。固定支持との差をこの例で1%以下にするks/kbは？','差はkb/ksなのでks/kb≥100です。これは1方向の直列例の結果で、他の構造へ万能な基準として使いません。'],
 ['400 mmの単純支持梁。左から100 mmで下向き120 N。左右の反力は？','RB×400−120×100=0よりRB=30 N、RA=90 N。合力90+30−120=0、左端まわりモーメント30×400−120×100=0です。']
 ];
 questions.push(['面積2 m²の境界を等面積の4区画に分けたら各ダンパは？','速度が一様なら各係数を元の1/4にして全体の抵抗を保ちます。節点での実装では、各点が負担する面積を集計します。'],['同位置の2節点間にばねを置き、同じ方向をMPCでも等置すると？','その方向の相対変位が0になるため、ばねの伸縮を表せません。意図が弾性継手なら重複した等置を見直します。']);
 questions.push(
 ['側面まで20 mのモデルでAから出たS波が0.20秒後に戻った。側面を40 mにしたら？','水平に同じ経路を往復し、Vs=200 m/sなら2×40÷200=0.40秒。地表や実際の地層は移動していないので、幅を変えたときの到達時刻の差が人工境界を識別する手掛かりです。'],
 ['本体地盤と自由地盤がともに右へ10 cm/s動く。側面のダンパーが伝える力と、側面の全力はともにゼロ？','速度差はゼロなので、相対速度に比例するダンパー力はゼロです。自由地盤の応力が切断面に及ぼす力は別に加わるので、全力がゼロとは決まりません。'],
 ['地表の加速度記録が手元にある。粘性底面の全節点に、その加速度を指定してよい？','まず記録の位置と波の定義を確認します。この例の粘性底面は入射波に相当する力を与えて、底面の運動を解きます。底面の運動を強制する方法とは境界の仮定が異なります。']);
 sections.push(['questions','自分で確かめる',p('先に条件を図や式へ書き、答えを開いて照合します。符号と座標系も答えの一部です。')+'<div class="theory-quiz">'+questions.map(([q,a],i)=>`<details><summary>${i+1}. ${q}</summary><p>${a}</p></details>`).join('')+'</div>']);
 sections.push(['sources','参照範囲と関連教材',
 p('説明と新しい操作図は、この章の学習順序に合わせて独自に構成しました。操作図は一般理論の計算であり、Nastran本体での実行結果ではありません。公式の入力リスト・出力一覧・図は転載していません。')+
 A.table(['資料','確認範囲'],[['MSC Nastran 2025.1 線形静解析ユーザーガイド','第6章 PDF235–252：SPC、自動拘束、指定変位、MPC、非同次拘束。第9章 PDF379–381：対称条件'],['MSC Nastran 2025.1 QRG','SPC 2882–2883、SPC1 2884–2885、SPCADD 2886、SPCD 2888–2890、MPC 2363、MPCADD 2364、MPCD 2366、MPCY 2367'],['同QRG：自動拘束・自由物体','AUTOSPC (Case) 266–268、旧PARAM 858、EPZERO 880、SUPORT 2919–2920、SUPORT1 2921'],['MIT OCW, K. J. Bathe','Finite Element Procedures for Solids and Structures：変位型有限要素法と境界条件'],['A. F. Bower, Applied Mechanics of Solids §7.1','境界条件、剛体運動、結合とモデル化の一般的な整理']])+
 p(source(stat+'#page=235','MSC 線形静解析ガイド 第6章')+' · '+source(stat+'#page=379','対称条件')+' · '+source(qrg+'#page=2882','QRG：SPC／SPCD')+' · '+source(qrg+'#page=2363','QRG：MPC')+' · '+source(qrg+'#page=266','QRG：AUTOSPC'))+
 p(source('https://ocw.mit.edu/courses/res-2-002-finite-element-procedures-for-solids-and-structures-spring-2010/resources/lecture-3/','MIT OCW：変位型有限要素法')+' · '+source('https://solidmechanics.org/Text/Chapter7_1/Chapter7_1.htm','Bower：有限要素解析の境界条件と結合'))+
 p(source('https://www.jstage.jst.go.jp/article/aijs/78/689/78_1263/_article/-char/ja/','秋田ほか：地盤・建物連成系のエネルギー伝達境界')+' · '+source('https://docs.itascacg.com/itasca920/flac3d/docproject/source/options/dynamic/considerations/considerations.html','Itasca：剛基盤・弾性基盤と入力地震動の整合'))+
 p(source('https://docs.itascacg.com/itasca900/3dec/docproject/source/options/dynamic/dynamic_boudaryconditions.html','Itasca：局所粘性境界と自由地盤境界の仮定')+' · '+source('https://www.jepoc.or.jp/upload/news/160725155459.pdf','電力中央研究所の講義資料：波長、底面・側方境界（スライド4–7）'))+
 note('一般理論はNastran共通です。カードの適用条件はMSC 2025.1を照合した範囲で記載しています。Siemens版の非線形手順・既定値まで同じと断定していません。')]);
 function html(){return '<div class="analysis-head"><span class="analysis-sol">境界条件と拘束</span><h1>境界条件と拘束の理論</h1><p>支持・指定変位・部材間の関係を分け、許す動きと伝わる力を、式・図・結果から判断します。</p></div>'+A.intro({goals:['実物が許す動きから、節点・成分・座標系を選ぶ','SPC・MPC・RBEの役割と、変位・反力の関係を理解する','拘束不足・過拘束・重複・自動拘束の問題を結果から見分ける'],prerequisites:[['coordinates.html#systems','座標'],['basics.html#node','節点と自由度'],['elements.html#element-families','要素の全体像']],points:['拘束は、点の数ではなく止める運動で決める。','独立・従属は節点と成分の組で追い、地面への支持と部材間の結合を分ける。','計算の終了だけで判断せず、変形・反力・拘束式・支持への感度で確かめる。']})+p('初めて学ぶ場合は1〜6節で支持の考え方を確認します。入力の使い分けは7節から、多点拘束は10節から、診断は18節から進めます。')+A.toc(sections.map(([id,title])=>['boundary-'+id,title]))+sections.map(([id,title,body],i)=>A.section(`${i+1}. ${title}`,body,'boundary-'+id)).join('');}
 const labels={'固定':'u = 0','対象成分を止める':'SPC','対称面':'n','法線の並進を止める':'un = 0','自由面':'t = 0','面荷重ゼロの例':'σn = 0','指定変位':'d','ばね力':'F = kd'};
 function connect(root){for(const el of root.querySelectorAll('[data-boundary-legacy]')){el.innerHTML=window.TheoryTopicVisuals.boundary[+el.dataset.boundaryLegacy].replace('uA − uB = 指定値','uA − r uB = 0');for(const t of el.querySelectorAll('svg text'))if(labels[t.textContent]!==undefined)t.textContent=labels[t.textContent];}window.BoundaryLabs.connect(root);window.MeshWaveLabs.connect(root);window.SoilBoundaryLabs.connect(root);A.bindNavigation(root);}
 const aliases={overview:'meaning',supports:'supports',spc:'sets',mpc:'mpc',connections:'rbe',verification:'autospc'};
 function focusSection(key){const t=document.getElementById('boundary-'+(aliases[key]||key));if(t)requestAnimationFrame(()=>t.scrollIntoView({block:'start'}));}
 function mount(root){root.innerHTML=html();connect(root);}
 window.BoundaryChapter={sections,questions,html,connect,mount,focusSection};
})();
